/* 구슬 레이스 — 코스 조각
 *
 * 트랙은 **한 화면보다 길다**(3~4화면). 한 화면에 다 넣으면 장애물을 몇 개 못 놓아
 * 출발 순서가 그대로 도착 순서가 되어 버린다 — 순위가 뒤집히는 구간이 여러 번 나와야
 * 지켜볼 이유가 생긴다. 대신 전체 판을 미니맵으로 항상 같이 보여 준다.
 *
 * 조각은 위에서 아래로 쌓는다. 각 조각은 자기 높이를 알고, 빌더가 `y` 를 밀어 준다.
 *
 * 치수 규약 (구슬 반지름 22):
 *  · 통로(장애물 표면 사이)는 **최소 58** — 좁으면 끼여서 판이 안 끝난다
 *  · 못은 벽에서 `2R + 못반지름 + 6` 이상 띄운다. 그보다 가까우면 구슬이 들어가지도
 *    지나가지도 못하는 틈이 생겨 거기 얹힌다 (1차본에서 13초 정지 실측)
 */
(function (global) {
  'use strict';

  /* 트랙 폭. 오른쪽 100px 은 미니맵 몫으로 비워 둔다 — 미니맵이 트랙을 덮으면
     "화면 밖에서 뭘 했는지 못 본다" 는 문제를 미니맵으로 푼 의미가 없다 */
  var LEFT = 40, RIGHT = 972;
  var MID = (LEFT + RIGHT) / 2;
  var R = 22;                          // 구슬 반지름 — 전 참가자 동일
  var PEG_R = 12;
  var SAFE_L = LEFT + 2 * R + PEG_R + 6;
  var SAFE_R = RIGHT - 2 * R - PEG_R - 6;

  function Builder(y0) {
    this.pegs = []; this.walls = []; this.rotors = []; this.seesaws = [];
    this.y = y0;
    this.marks = [];                   // 구간 이름 — 미니맵에 눈금으로 쓴다
  }

  Builder.prototype.peg = function (x, y, r, opt) {
    var p = { x: x, y: y, r: r == null ? PEG_R : r };
    if (opt) { if (opt.e != null) p.e = opt.e; if (opt.bump) p.bump = 1; if (opt.kick) p.kick = opt.kick; }
    this.pegs.push(p);
    return this;
  };
  Builder.prototype.wall = function (x1, y1, x2, y2, r, opt) {
    var w = { x1: x1, y1: y1, x2: x2, y2: y2, r: r == null ? 12 : r };
    if (opt) { if (opt.e != null) w.e = opt.e; if (opt.sv) w.sv = opt.sv; }
    this.walls.push(w);
    return this;
  };
  Builder.prototype.rotor = function (x, y, len, w, bars, a0, r) {
    this.rotors.push({ x: x, y: y, len: len, r: r == null ? 13 : r, w: w, bars: bars || 1, a0: a0 || 0 });
    return this;
  };
  Builder.prototype.seesaw = function (x, y, len, opt) {
    opt = opt || {};
    this.seesaws.push({
      x: x, y: y, len: len, r: opt.r == null ? 13 : opt.r,
      a0: opt.a0 || 0, k: opt.k == null ? 6.5 : opt.k, damp: opt.damp == null ? 1.4 : opt.damp,
      max: opt.max == null ? 0.42 : opt.max, gain: opt.gain == null ? 0.00055 : opt.gain
    });
    return this;
  };
  Builder.prototype.mark = function (name) { this.marks.push({ y: this.y, name: name }); return this; };

  /** 벽에 붙은 삼각 킥커 — 없으면 가장자리가 장애물 없는 고속 차선이 된다 */
  Builder.prototype.kicker = function (side, y, w, h) {
    var x = side < 0 ? LEFT : RIGHT;
    return this.wall(x, y, x + side * w, y + h, 11);
  };

  /** 선분 위 x 지점의 y */
  function lineY(ax, ay, bx, by, x) {
    var t = (bx - ax) === 0 ? 0 : (x - ax) / (bx - ax);
    return ay + (by - ay) * t;
  }

  /**
   * 비탈 **위에** 못을 매단다. 비탈면과의 통로를 `2R + 12` 로 강제한다.
   * 1차본은 못을 비탈에 파묻어 **넘을 수 없는 턱**을 만들었고, 구슬 하나가 거기서 60초를
   * 버텼다. 눈으로는 안 보이고 통과 시험으로만 잡힌다.
   */
  Builder.prototype.hangPeg = function (a, x, r) {
    r = r == null ? 12 : r;
    var y = lineY(a.x1, a.y1, a.x2, a.y2, x);
    return this.peg(x, y - a.r - r - (2 * R + 12), r);
  };

  /**
   * 출발 통 — **구슬을 한 통에 담아 쏟는다.**
   * 화면 폭 전체에 한 줄로 세우면 코스가 섞을 일이 없어 출발 자리가 그대로 순위가 된다
   * (실측: 폭포 코스에서 출발 x ↔ 등수 스피어만 ρ = −0.27). 한 곳에 모아 쏟으면
   * 출발 자리라는 게 사실상 없어지고, 섞는 일을 코스가 전부 하게 된다.
   */
  Builder.prototype.hopper = function (startY) {
    this.mark('출발');
    var halfW = 148, wr = 12;
    // 통 벽
    this.wall(MID - halfW, startY - 150, MID - halfW, startY + 44, wr);
    this.wall(MID + halfW, startY - 150, MID + halfW, startY + 44, wr);
    // 아래 깔때기 — 좁은 목으로 한꺼번에 쏟아진다
    this.wall(MID - halfW, startY + 44, MID - 74, startY + 168, wr);
    this.wall(MID + halfW, startY + 44, MID + 74, startY + 168, wr);
    this.y = startY + 196;
    return this;
  };

  /* ── 조각들 ───────────────────────────────────────────────────────────── */

  /** 갈톤 보드 — 못에 맞을 때마다 좌우로 갈린다 */
  Builder.prototype.pegField = function (rows, dy) {
    dy = dy || 88;
    this.mark('못밭');
    var y0 = this.y + 54;
    for (var r = 0; r < rows; r++) {
      var y = y0 + r * dy;
      var odd = r % 2;
      for (var k = -5; k <= 5; k++) {
        var x = MID + (k + (odd ? 0.5 : 0)) * 98;
        if (x < SAFE_L || x > SAFE_R) continue;
        this.peg(x, y);
      }
      if (r % 3 === 1) this.kicker(r % 2 ? -1 : 1, y - 34, 74, 92);
    }
    this.y = y0 + (rows - 1) * dy + 74;
    return this;
  };

  /** 지그재그 비탈 — 끝단에서 떨어지며 병목이 생긴다 */
  Builder.prototype.zigzag = function (n, dy) {
    this.mark('지그재그');
    var y0 = this.y + 40;
    var drop = 168;                        // 낙차. 완만하면 구슬이 굴러가지 않고 선다(5°에서 정지 실측)
    // **비탈 간격은 낙차보다 구슬 지름 이상 커야 한다.** 좁으면 위 비탈의 끝과 아래 비탈
    // 사이에 V 자 주머니가 생겨 구슬이 거기 박힌다 (dy=186 일 때 전량 정지 실측)
    dy = Math.max(dy || 0, drop + 2 * R + 52);
    for (var i = 0; i < n; i++) {
      var y = y0 + i * dy;
      var toRight = (i % 2) === 0;
      var a;
      if (toRight) {
        this.wall(LEFT - 6, y, RIGHT - 190, y + drop, 13);
        a = this.walls[this.walls.length - 1];
        this.hangPeg(a, MID - 190, 13);
        this.hangPeg(a, MID + 10, 13);
        this.hangPeg(a, MID + 200, 13);
      } else {
        this.wall(RIGHT + 6, y, LEFT + 190, y + drop, 13);
        a = this.walls[this.walls.length - 1];
        this.hangPeg(a, MID + 190, 13);
        this.hangPeg(a, MID - 10, 13);
        this.hangPeg(a, MID - 200, 13);
      }
    }
    this.y = y0 + (n - 1) * dy + drop + 90;
    return this;
  };

  /** 회전 십자 — 순위를 가장 크게 뒤집는 구간 */
  Builder.prototype.rotorRow = function (n, speed) {
    this.mark('회전 십자');
    var y = this.y + 150;
    var span = (RIGHT - LEFT) / n;
    // 날개 길이는 개수에서 역산한다 — 고정값으로 두면 개수를 늘리는 순간
    // 회전체끼리, 또는 레일과의 사이가 구슬보다 좁아져 거기서 판이 멈춘다
    var rr = 12;
    var arm = Math.max(46, span / 2 - rr - (2 * R + 10));
    for (var i = 0; i < n; i++) {
      var x = LEFT + span * (i + 0.5);
      var dir = (i % 2 ? -1 : 1);
      this.rotor(x, y, arm, dir * (speed || 2.0), 2, i * 0.6, rr);
    }
    // 회전체 사이로 흘러내리지 않도록 아래에 받침 못
    for (i = 0; i < n + 1; i++) {
      var px = LEFT + span * i;
      if (px < SAFE_L || px > SAFE_R) continue;
      this.peg(px, y + 168, 14);
    }
    this.y = y + 236;
    return this;
  };

  /** 시소 — 앞선 구슬의 무게가 뒤따르는 구슬의 길을 바꾼다 */
  Builder.prototype.seesawRow = function () {
    this.mark('시소');
    var y = this.y + 122;
    // 길이·위치는 통로에서 역산한다: 레일과 52 이상, 두 시소 사이도 52 이상
    this.seesaw(MID - 220, y, 170, { a0: 0.16 });
    this.seesaw(MID + 220, y, 170, { a0: -0.16 });
    this.peg(MID, y - 46, 16);
    this.peg(LEFT + 88, y + 150, 14);
    this.peg(RIGHT - 88, y + 150, 14);
    this.peg(MID, y + 150, 14);
    this.y = y + 224;
    return this;
  };

  /** 범퍼 — 세게 튕겨 낸다. 핀볼의 그 맛 */
  Builder.prototype.bumpers = function () {
    this.mark('범퍼');
    var y = this.y + 118;
    var opt = { e: 0.55, kick: 640, bump: 1 };
    this.peg(MID, y, 40, opt);
    this.peg(MID - 232, y + 92, 36, opt);
    this.peg(MID + 232, y + 92, 36, opt);
    this.peg(MID - 116, y + 214, 32, opt);
    this.peg(MID + 116, y + 214, 32, opt);
    this.wall(LEFT - 6, y - 66, LEFT + 128, y + 84, 12);
    this.wall(RIGHT + 6, y - 66, RIGHT - 128, y + 84, 12);
    this.y = y + 300;
    return this;
  };

  /** 컨베이어 — 표면이 흐른다. 어느 벨트에 얹히느냐로 갈린다 */
  Builder.prototype.belts = function (speed) {
    this.mark('컨베이어');
    var y = this.y + 108;
    var s = speed || 320;
    this.wall(LEFT - 6, y, MID - 78, y + 46, 14, { sv: s });
    this.wall(RIGHT + 6, y + 128, MID + 78, y + 174, 14, { sv: s });
    this.peg(MID + 168, y + 92, 14);
    this.peg(MID - 168, y + 216, 14);
    this.y = y + 282;
    return this;
  };

  /**
   * 관문 — 가로 칸막이에 구멍 몇 개. 여기서 병목이 크게 걸린다.
   * **수평 벽으로 만들면 안 된다** — 구슬이 그 위에 그대로 서서 판이 안 끝난다.
   * 칸막이는 구멍 쪽으로 기운 ⋀ 여야 어디에 떨어져도 굴러서 구멍을 찾는다.
   */
  /**
   * @param holes 구멍 개수
   * @param clear 구슬이 지나갈 **실제 폭**. 기본 104(넉넉) · 56 이면 지름 44 에 여유 12 뿐
   */
  Builder.prototype.gates = function (holes, clear) {
    this.mark('관문');
    var y = this.y + 96;
    var n = holes || 3;
    var span = RIGHT - LEFT;
    var gapW = (clear == null ? 104 : clear) + 24, rise = 40;
    for (var row = 0; row < 2; row++) {
      var yy = y + row * 150;
      var hs = [];
      for (var i = 0; i < n; i++) {
        var cx = LEFT + span * ((i + 0.5 + (row ? 0.5 : 0)) / n);
        if (cx - gapW / 2 > LEFT + 10 && cx + gapW / 2 < RIGHT - 10) hs.push(cx);
      }
      if (!hs.length) hs.push(MID);
      var edges = [LEFT - 8];
      for (i = 0; i < hs.length; i++) edges.push(hs[i] - gapW / 2, hs[i] + gapW / 2);
      edges.push(RIGHT + 8);
      for (i = 0; i + 1 < edges.length; i += 2) {
        var x1 = edges[i], x2 = edges[i + 1];
        if (x2 - x1 < 8) continue;
        var atLeftRail = (i === 0), atRightRail = (i + 2 >= edges.length);
        if (atLeftRail && !atRightRail) {
          // 레일에 붙은 칸막이는 **구멍 쪽으로만** 내려가야 한다.
          // ⋀ 로 만들면 레일과의 사이에 빠져나올 수 없는 주머니가 생긴다
          this.wall(x1, yy - rise, x2, yy, 12);
        } else if (atRightRail && !atLeftRail) {
          this.wall(x1, yy, x2, yy - rise, 12);
        } else {
          var mx = (x1 + x2) / 2;
          this.wall(x1, yy, mx, yy - rise, 12);
          this.wall(mx, yy - rise, x2, yy, 12);
        }
      }
    }
    this.y = y + 150 + 108;
    return this;
  };

  /**
   * 슬라롬 — ⋀ 사이를 훑고 지나간다.
   * 세로 기둥으로 만들면 둥근 꼭대기에 구슬이 얹혀 버린다(통과 시험에서 3/37 정지).
   */
  Builder.prototype.slalom = function (rows) {
    this.mark('슬라롬');
    var y0 = this.y + 76;
    // ⋀ 한 개의 크기와 줄 간격은 **구슬이 지나갈 통로**에서 역산한다.
    // 1차본은 가로 74 / 세로 40 만 남겨 전량이 여기서 멈췄다
    var half = 38, up = 26, down = 30, wr = 11;
    var dx = 178, dy = 176;
    for (var r = 0; r < rows; r++) {
      var y = y0 + r * dy;
      var odd = r % 2;
      for (var k = -2; k <= 2; k++) {
        var x = MID + (k + (odd ? 0.5 : 0)) * dx;
        // **레일 쪽으로 기울어진 면을 만들면 안 된다** — 레일과의 사이가 빠져나올 수 없는
        // 주머니가 된다. 양쪽 다 통로가 남는 자리에만 놓는다
        if (x - half - wr < LEFT + 2 * R + 8) continue;
        if (x + half + wr > RIGHT - 2 * R - 8) continue;
        this.wall(x - half, y + down, x, y - up, wr);
        this.wall(x, y - up, x + half, y + down, wr);
      }
    }
    this.y = y0 + (rows - 1) * dy + 132;
    return this;
  };

  /**
   * 마지막 관문 — 결승 바로 앞. **모든 맵이 이걸로 끝난다.**
   * 여기가 결과가 확정되는 유일한 지점이라 가장 조마조마해야 한다. 세 단계다:
   *   ① 범퍼 밭에서 한 번 흩어지고
   *   ② 깔때기로 가운데에 모이고
   *   ③ **좁고 긴 수직 통로**를 한 줄로 지나간다. 입구 어깨에 범퍼가 있어
   *      들어가려다 튕겨 나간다 — 이 한 번이 이 게임의 마지막 긴장이다
   */
  Builder.prototype.finishGate = function () {
    this.mark('마지막 관문');
    var bo = { e: 0.5, kick: 600, bump: 1 };
    var y = this.y + 100;

    // ① 범퍼 밭
    this.peg(MID, y, 34, bo);
    this.peg(MID - 232, y + 26, 30, bo);
    this.peg(MID + 232, y + 26, 30, bo);
    this.peg(MID - 116, y + 142, 28, bo);
    this.peg(MID + 116, y + 142, 28, bo);
    this.peg(MID - 348, y + 142, 26, bo);
    this.peg(MID + 348, y + 142, 26, bo);

    // ② 깔때기 — 통로 폭에서 역산해 벽 끝을 통로 벽과 정확히 잇는다.
    //    어긋나면 이음매가 빠져나올 수 없는 주머니가 된다
    var wr = 13;
    var half = (2 * R + 10) / 2;          // 통과 폭 절반 (구슬 지름 + 10)
    var edge = half + wr;                 // 통로 벽 중심선
    var fy = y + 240;
    this.wall(LEFT - 6, fy, MID - edge, fy + 196, wr);
    this.wall(RIGHT + 6, fy, MID + edge, fy + 196, wr);

    // ③ 좁고 긴 통로 + 입구 어깨 범퍼
    var cy = fy + 196;
    var len = 320;
    this.wall(MID - edge, cy, MID - edge, cy + len, wr);
    this.wall(MID + edge, cy, MID + edge, cy + len, wr);
    this.peg(MID - edge - 40, cy - 10, 24, bo);
    this.peg(MID + edge + 40, cy - 10, 24, bo);

    this._gated = true;
    this.y = cy + len + 24;
    return this;
  };

  /** 마지막 깔때기 + 결승선. 여기서 카메라가 붙는다 */
  Builder.prototype.finish = function () {
    this.mark('결승');
    var y = this.y + 30;
    // 마지막 관문을 지났으면 이미 한 줄로 모였다 — 깔때기를 또 두면 이음매만 늘어난다.
    // 통로 출구와 결승선 사이는 짧게 — 비어 있으면 죽은 구간으로 보인다
    if (!this._gated) {
      this.wall(LEFT - 4, y, MID - 150, y + 150, 14);
      this.wall(RIGHT + 4, y, MID + 150, y + 150, 14);
      this.y = y + 218;
    } else {
      this.y = y + 80;
    }
    return { finishY: this.y };
  };

  Builder.prototype.build = function (key, name, tag, phys) {
    var f = this.finish();
    return {
      key: key, name: name, tag: tag,
      pegs: this.pegs, walls: this.walls, rotors: this.rotors, seesaws: this.seesaws,
      marks: this.marks,
      finishY: f.finishY,
      length: f.finishY,
      gravity: phys.gravity, restitution: phys.restitution,
      friction: phys.friction, drag: phys.drag
    };
  };

  global.Parts = {
    Builder: Builder,
    LEFT: LEFT, RIGHT: RIGHT, MID: MID, R: R, PEG_R: PEG_R, SAFE_L: SAFE_L, SAFE_R: SAFE_R
  };
})(window);

