/* 구슬 레이스 — 맵
 *
 * 맵은 **매 판 고정**이다. 판을 판마다 흔들면 "이 판이 나한테 불리하게 생겼다" 는 의심을
 * 지울 수 없다 — 모두가 같은 판에서, 출발 자리만 무작위로 섞어 달린다.
 * 그래서 맵은 좌우 대칭으로 짜고, 무작위는 오직 출발 자리 배정과 아주 작은 초기 흔들림뿐이다.
 *
 * 각 맵은 성격이 다른 구간을 4~6개 이어 붙인 3~4화면짜리 트랙이다. 한 구간만으로는
 * 출발 순서가 그대로 도착 순서가 되어 끝까지 볼 이유가 없다.
 */
(function (global) {
  'use strict';

  var P = Parts;
  var START_Y = 300;   // 출발 통이 상단 HUD 뒤로 들어가지 않게 내려 잡는다

  function make(key, name, tag, phys, plan) {
    var b = new P.Builder(START_Y);
